import { useEffect, useState } from 'react';
import './scrollup.css';

export function ScrollUp() {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const updateVisibility = () => setVisible(window.scrollY > 500);
    window.addEventListener('scroll', updateVisibility, { passive: true });
    updateVisibility();
    return () => window.removeEventListener('scroll', updateVisibility);
  }, []);

  return (
    <a href="#home" className={`scrollup${visible ? ' show-scroll' : ''}`} aria-label="Back to top" tabIndex={visible ? 0 : -1}>
      <i className="uil uil-arrow-up scrollup__icon" aria-hidden="true"></i>
    </a>
  );
}
